<?php
declare(strict_types=1);namespace App\Controllers;use App\Core\Csrf;use App\Core\Response;use App\Core\Session;use App\Core\TenantContext;use App\Core\View;use App\Repositories\AuditLogRepository;use App\Repositories\InvitationQuestionRepository;use App\Repositories\InvitationRepository;use PDO;
final class QuestionAdminController{public function __construct(private readonly PDO $pdo){}public function index(int $inv):void{$t=$this->tenant($inv);View::render('admin.events.questions',['title'=>'신청 질문 관리','invitationId'=>$inv,'questions'=>(new InvitationQuestionRepository($this->pdo))->listForTenant($t,$inv),'success'=>Session::pullFlash('success'),'error'=>Session::pullFlash('error')]);}public function save(int $inv):void{Csrf::verify($_POST['_token']??null);$t=$this->tenant($inv);$type=(string)($_POST['question_type']??'');$label=trim((string)($_POST['label']??''));$options=array_values(array_filter(array_map('trim',explode("\n",(string)($_POST['options']??'')))));if(mb_strlen($label)<1||mb_strlen($label)>190||!in_array($type,['text','textarea','select','checkbox'],true)||(($type==='select')&&$options===[])){Session::flash('error','질문, 유형과 선택 항목을 확인해 주세요.');Response::redirect('/admin/events/'.$inv.'/questions');}$id=(new InvitationQuestionRepository($this->pdo))->save($t,$inv,(int)($_POST['id']??0),['label'=>$label,'question_type'=>$type,'options_json'=>$options?json_encode($options,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR):null,'is_required'=>isset($_POST['is_required'])?1:0,'sort_order'=>max(0,min(1000,(int)($_POST['sort_order']??0)))]);$this->audit($t,$id,'event_question.saved');Session::flash('success','질문을 저장했습니다.');Response::redirect('/admin/events/'.$inv.'/questions');}public function deactivate(int $inv,int $id):void{Csrf::verify($_POST['_token']??null);$t=$this->tenant($inv);if(!(new InvitationQuestionRepository($this->pdo))->deactivate($t,$inv,$id))Response::abort(404,'질문을 찾을 수 없습니다.');$this->audit($t,$id,'event_question.deactivated');Response::redirect('/admin/events/'.$inv.'/questions');}private function tenant(int $inv):TenantContext{$t=TenantContext::fromSession();if(!in_array($t->role(),['owner','admin'],true))Response::abort(403,'관리자 권한이 필요합니다.');if((new InvitationRepository($this->pdo))->findForTenant($t,$inv)===null)Response::abort(404,'초대장을 찾을 수 없습니다.');return$t;}private function audit(TenantContext $t,int $id,string $a):void{$u=Session::get('auth',[]);(new AuditLogRepository($this->pdo))->record((int)($u['user_id']??0),$t->churchId(),$a,'invitation_form_question',$id);}}
